//! The `reason` registry (design §44 §7.4, D611; runtime contract R8).
//!
//! A `reason` is the stable, `snake_case` cause of a failed RPC, registered in
//! `docs/api/reasons.md`. It is what a caller branches on; the `message` is for
//! a person and may change. The registry's rule is that a reason may be **added**
//! but never renamed or removed within an API major version, so this list only
//! grows.
//!
//! The TypeScript SDK's copy of this table is generated by
//! `protoc-gen-loams-facade` into `src/gen/facade.ts`, and the Rust SDK's copy
//! is generated into `src/facade.rs` (`facade::REASONS` and
//! `facade::REASON_CODES`, D641).
//!
//! This enum is the runtime's own, and stays hand-written: the generated table
//! carries the reasons as `&'static str` constants, which is what a caller
//! matches on and what keeps a reason from becoming an enum variant that a
//! server the SDK has never spoken to could not name. `rust_error_reason_mapping`
//! walks every row here and fails if the registry page, this enum and the
//! generated table drift apart, so a reason added to `docs/api/reasons.md`
//! without a row here cannot pass unnoticed.

use connectrpc::ErrorCode as Code;

/// A stable, machine-readable cause of a failed RPC.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[non_exhaustive]
pub enum Reason {
    /// The approval this call needed is past its deadline.
    ApprovalExpired,
    /// The approval was already decided, so there is nothing to decide again.
    ApprovalAlreadyDecided,
    /// The approval was written against an older revision of what it approves.
    ApprovalStaleRevision,
    /// The caller is the requester, and a requester cannot approve their own request.
    RequesterCannotApprove,
    /// The decision proof does not verify against the instance key.
    DecisionProofInvalid,
    /// The call needs a fresh authentication step before it can proceed.
    StepUpRequired,
    /// A free-text reason is required and none was given.
    ReasonRequired,
    /// The decision is not one of approve, deny or request changes.
    InvalidDecision,
    /// The pairing grant is past its deadline.
    PairingExpired,
    /// The pairing grant was already used; a grant is single use.
    PairingUsed,
    /// The device was revoked, by its owner or by the instance.
    DeviceRevoked,
    /// The push target is not registered with the instance.
    PushTargetUnknown,
    /// This build does not implement the call.
    NotImplemented,
    /// This build variant does not carry the package the call belongs to.
    FeatureNotInVariant,
    /// A `loams.house.v1` call on a server with no House front configured.
    HouseNotConfigured,
    /// A House statement that does not parse, or is outside the House surface.
    HouseSyntaxError,
    /// The table a House statement names does not exist.
    HouseUnknownTable,
    /// The database a House statement names does not exist.
    HouseUnknownDatabase,
    /// The caller may not run this House statement or query operation.
    HouseAccessDenied,
    /// A read-only House statement tried to write or change state.
    HouseReadOnly,
    /// The House statement ran past its timeout.
    HouseTimeout,
    /// The House statement exceeded its memory limit.
    HouseMemoryLimit,
    /// No House worker was free within the acquire timeout.
    HouseTooManyQueries,
    /// The House statement is past a namespace quota.
    HouseQuotaExceeded,
    /// The statement uses a function, engine or table the House deny list refuses.
    HouseDisabledFunction,
    /// The House statement was cancelled.
    HouseCancelled,
    /// The House query the call names was not found.
    HouseQueryNotFound,
    /// The House engine raised an error with no more specific reason.
    HouseQueryFailed,
    /// The project a `loams.postgres.v1` call names does not exist.
    ProjectNotFound,
    /// The branch has child branches, so it cannot be deleted.
    BranchHasChildren,
    /// The branch is protected and cannot be deleted or restored over.
    BranchProtected,
    /// The requested LSN is older than the history retention.
    LsnOutOfRetention,
    /// The branch already has a read-write endpoint.
    EndpointExistsForBranch,
    /// The compute could not be started.
    ComputeStartFailed,
    /// A create or resize would go past a quota.
    QuotaExceeded,
    /// The storage layer the call needs is down.
    StorageUnavailable,
    /// The secret was already issued for this idempotency key and is answered once.
    SecretAlreadyIssued,
    /// The named Loams Git repository does not exist.
    RepoNotFound,
    /// A Loams Git repository of that name already exists.
    RepoAlreadyExists,
    /// The repository was deleted and is waiting to be purged.
    RepoDeleting,
    /// A ref write's expected old value no longer holds.
    RefStale,
    /// A protection rule refuses the ref write.
    RefProtected,
    /// The write is outside the credential's branch prefixes or cones.
    OutOfScope,
    /// The repository's object format is not supported (SHA-1 only for now).
    ObjectFormatUnsupported,
    /// The source repository is already as many forks deep as allowed.
    ForkTooDeep,
    /// The repository's sequencer is shutting down, lost its lease, or could not open.
    SequencerUnavailable,
    /// The idempotency key was used inside its window for a different request.
    IdempotencyKeyReused,
    /// The named workspace does not exist.
    WorkspaceNotFound,
    /// Another writer appended the workspace snapshot first.
    WorkspaceFenced,
    /// The workspace or snapshot is read-only.
    WorkspaceReadOnly,
    /// The owner already has a workspace of that name.
    WorkspaceNameTaken,
    /// A snapshot or push names an object the repository does not have.
    ObjectMissing,
    /// The leak scanner found a credential outside `env/`.
    SecretDetected,
    /// An `env/` file holds a plaintext value.
    EnvUnsealed,
    /// The credential has no grant for the environment.
    EnvAccessDenied,
    /// A sealed `env/` reference names another repository's secret.
    EnvForeignReference,
    /// A Live function's `paginate` got a malformed, altered or foreign cursor.
    LiveBadCursor,
    /// The isolated worker running a Live function crashed; the call never committed.
    LiveWorkerCrashed,
    /// Another Live deploy activated first, so `expected_active` no longer matches.
    LiveDeployConflict,
    /// A write did not match its Live table's validator; the message names the table and field paths.
    LiveSchemaViolation,
    /// A Live function read an index a deploy is still backfilling.
    LiveIndexNotReady,
    /// A call to a Live app that is disabled or deleted.
    LiveAppDisabled,
    /// CreateApp named a Live app that already exists.
    LiveAppExists,
    /// A deployed Live function threw.
    LiveFunctionError,
    /// A Live function ran past its CPU limit.
    LiveFunctionTimeout,
    /// A Live function ran past its memory limit.
    LiveFunctionOutOfMemory,
    /// A Live call exceeded one of the app's limits.
    LiveLimitExceeded,
    /// A credential reached a Live app outside its environment.
    LiveAppMismatch,
    /// A browser origin the addressed Live app does not allow.
    LiveOriginNotAllowed,
    /// A Live session reached its maximum age; resume it.
    SessionRotate,
    /// The caller's org role is below the one the admin RPC needs, or the caller is not in the org.
    RoleRequired,
    /// First-run setup has not created the org yet.
    SetupRequired,
    /// The call carried no credential.
    TokenMissing,
    /// The credential is not an API key, a session token or a JWT, or more than one Authorization header was sent.
    TokenMalformed,
    /// The API key was revoked, or the console session was signed out or its person left the org.
    TokenRevoked,
    /// The OIDC token's nbf is in the future.
    TokenNotYetValid,
    /// The OIDC token's signature does not verify.
    TokenBadSignature,
    /// The OIDC token is for another audience.
    TokenWrongAudience,
    /// The OIDC token is from an issuer this engine does not trust.
    TokenWrongIssuer,
    /// The OIDC token is signed with a key its issuer's JWKS does not have.
    TokenUnknownKey,
    /// The OIDC token is signed with an algorithm other than RS256 or EdDSA.
    TokenAlgorithmNotAllowed,
    /// No key file or metastore record admits the API key.
    ApiKeyInvalid,
    /// This engine's auth mode does not take this kind of credential.
    CredentialNotAccepted,
    /// A credential was sent in the query string.
    CredentialInQueryString,
    /// A cookie-authenticated call that is not a GET lacked the session's CSRF token.
    CsrfTokenInvalid,
    /// A valid OIDC or tailnet identity that is not on the engine's allowlist.
    PrincipalNotAllowed,
    /// A browser call from an origin the engine's CORS allowlist does not have.
    CorsOriginNotAllowed,
    /// The credential cannot be checked now: the issuer's JWKS or the principal store is unreachable.
    AuthUnavailable,
    /// An argument is missing, malformed or out of range.
    InvalidArgument,
    /// The thing the call names does not exist.
    NotFound,
    /// The thing the call would create already exists.
    AlreadyExists,
    /// The caller is authenticated but not allowed to do this.
    PermissionDenied,
    /// The bearer the call carried has expired; refresh and retry once.
    TokenExpired,
    /// The call carried no usable credential.
    Unauthenticated,
    /// The system is not in a state where the call can be made.
    FailedPrecondition,
    /// A quota or a rate limit was reached.
    ResourceExhausted,
    /// The service is temporarily unavailable; a retry may succeed.
    Unavailable,
    /// The call ran out of time.
    DeadlineExceeded,
    /// The call was aborted; a retry may succeed.
    Aborted,
    /// A fault on the server.
    Internal,
}

